import {speakingView,mountSpeaking,leaveSpeaking} from './speaking.js';
import {schedule,parseWords,normalize,dateKey,streak} from './engine.js';
const $=s=>document.querySelector(s),e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const seeds=[
 ['resilient','qiyinchilikdan tez tiklanadigan','She remained resilient in the face of adversity.','IELTS Essential','B2'],
 ['ubiquitous','hamma joyda uchraydigan','Smartphones have become ubiquitous.','IELTS Essential','C1'],
 ['substantial','sezilarli; katta','The project requires substantial investment.','IELTS Essential','B2'],
 ['consequently','natijada; shu sababli','It rained heavily; consequently, the match was cancelled.','IELTS Essential','B2'],
 ['sustainable','barqaror; uzoq davom eta oladigan','We need more sustainable sources of energy.','IELTS Essential','B2'],
 ['meticulous','juda sinchkov','She is meticulous about her research.','IELTS Essential','C1'],
 ['achieve','erishmoq','You can achieve your goals with practice.','Everyday English','B1'],
 ['improve','yaxshilamoq','Reading helps improve your vocabulary.','Everyday English','A2'],
 ['opportunity','imkoniyat','This is a great opportunity to learn.','Everyday English','B1'],
 ['confident','o‘ziga ishongan','I feel more confident when I practise.','Everyday English','B1'],
 ['take into account','hisobga olmoq','We must take the cost into account.','Academic Collocations','B2'],
 ['play a vital role','muhim rol o‘ynamoq','Education plays a vital role in society.','Academic Collocations','B2'],
 ['draw a conclusion','xulosa chiqarmoq','We can draw a conclusion from these results.','Academic Collocations','B2'],
 ['conduct research','tadqiqot o‘tkazmoq','Scientists conduct research to test ideas.','Academic Collocations','B2']
];
const blank=()=>({version:1,name:'O‘rganuvchi',goal:10,xp:0,log:{},spell:{right:0,total:0},completed:[],cards:seeds.map(([word,translation,example,deck,level])=>({id:uid(),word,translation,example,deck,level,due:0,reps:0,reviews:0,interval:0,ease:2.5}))});
let state,storageOK=true;
try{const raw=localStorage.getItem('lexora.v1');state=raw?JSON.parse(raw):blank();if(!state||state.version!==1||!Array.isArray(state.cards)||!state.log||!state.spell)throw Error();}catch{state=blank();}
let route='home',search='',deckFilter='',session=null,spelling=null,showBack=false,toastTimer;
try{const cached=JSON.parse(sessionStorage.getItem('lexora.study')||'null');if(cached&&Array.isArray(cached.ids)&&Number.isInteger(cached.index)&&cached.index>=0&&cached.index<=cached.ids.length&&Number.isInteger(cached.done)&&cached.done>=0&&cached.ids.every(id=>typeof id==='string'))session=cached;}catch{}
const nav=[['home','home','O‘qish stoli'],['vocab','book','Lug‘at'],['spell','edit','Imlo'],['speaking','mic','Speaking'],['courses','course','Qisqa darslar'],['analytics','chart','Natijalar'],['telegram','group','Guruhlar'],['settings','settings','Sozlamalar']];
function icon(id){const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5C9 3 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-6-1-9 1v15"/>',edit:'<path d="m4 16-1 5 5-1L21 7l-4-4L4 16ZM14 6l4 4"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',course:'<path d="m2 8 10-5 10 5-10 5L2 8Zm4 3v6c4 3 8 3 12 0v-6M22 8v8"/>',chart:'<path d="M3 3v18h18M7 16v-4m5 4V7m5 9v-6"/>',group:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3M17 5a3 3 0 0 1 0 6m2 3a4 4 0 0 1 3 4v2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(paths[id]||paths.book)+'</svg>';}
const windowIcon=icon;
const uzDays=['Ya','Du','Se','Ch','Pa','Ju','Sh'],uzMonths=['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentabr','oktabr','noyabr','dekabr'];
function shortDate(d){return d.getDate()+' '+uzMonths[d.getMonth()];}
const btn=(text,action,cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${text}</button>`;
const due=()=>state.cards.filter(c=>c.due<=Date.now());
const today=()=>state.log[dateKey()]||0;
const decks=()=>[...new Set([...(state.deckNames||[]),...state.cards.map(c=>c.deck)])];
function save(){try{localStorage.setItem('lexora.v1',JSON.stringify(state));}catch{storageOK=false;toast('Saqlash uchun brauzer xotirasi yetarli emas. Zaxira nusxasini yuklab oling.');}updateHeader();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function updateHeader(){$('#xp').textContent=`ϟ ${state.xp} XP`;$('#streak').textContent=`♨ ${streak(state.log)} kun`;$('#profile-name').innerHTML=`${e(state.name)}<small>Mustaqil o‘rganuvchi</small>`;}
function heading(label,title,sub,right=''){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${sub}</p></div>${right}</div>`;}
function stat(icon,value,label){return `<div class="stat"><span class="stat-icon">${icon}</span><div class="num">${value}<small>${label}</small></div></div>`;}
function deckRows(){return decks().map((name,i)=>{const cards=state.cards.filter(c=>c.deck===name),n=cards.filter(c=>c.due<=Date.now()).length,pct=cards.length?Math.round(cards.filter(c=>c.reps>0).length/cards.length*100):0;return `<div class="deck"><span class="deck-icon">${['▤','Aa','✦'][i%3]}</span><div class="deck-copy"><h3>${e(name)}</h3><small>${cards.length} so‘z · ${n} ta takrorlash uchun</small><div class="progress"><span style="width:${pct}%"></span></div></div><button class="btn" data-study="${e(name)}">O‘rganish ↗</button></div>`;}).join('')||'<div class="empty">Birinchi so‘zingizni qo‘shing.</div>';}
function home(){const n=due().length,week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d;}),remaining=lessons.filter(l=>!state.completed.includes(l.id)).length;return heading('LEXORA / O‘QUV MAYDONI','O‘qish stoli',`Xush kelibsiz, ${e(state.name)}. Bugungi mashg‘ulotlaringiz shu yerda.`,`<span class="pill">${shortDate(new Date())}</span>`)+`<div class="desk-grid"><div><section class="next-session"><span class="eyebrow">${n?'DAVOM ETTIRISH UCHUN':'BUGUNGI TAKRORLASH'}</span><h2>${n?'Bilimingizni<br>yodga oling.':'Bugungi navbat<br>yakunlangan.'}</h2><p>${n?n+' ta so‘z takrorlashni kutyapti. Javobni ochishdan oldin inglizchasini eslashga harakat qiling.':'Hozircha takrorlash vaqti kelgan so‘z yo‘q. Qisqa dars yoki speaking bilan davom etishingiz mumkin.'}</p><span class="session-number">${String(n).padStart(2,'0')}</span><div class="session-bottom"><span>Lug‘at · O‘zbekcha → Inglizcha</span>${n?btn('Takrorlashni boshlash →','study','primary'):'<button class="btn primary" data-route="speaking">Speaking’ga o‘tish →</button>'}</div></section><section class="desk-section"><div class="section-head"><h2>Bugungi mashqlar</h2><span class="count">O‘z sur’atingizda</span></div><div class="practice-list"><button class="practice-row" data-route="spell"><span class="row-number">01</span><div class="practice-copy"><h3>So‘zlarni yozib mustahkamlash</h3><p>Tarjimaga qarab yozing, xatolar ustida qayta ishlang.</p></div><span class="row-meta">Imlo · 10 tagacha so‘z</span><span class="row-arrow">↗</span></button><button class="practice-row" data-route="speaking"><span class="row-number">02</span><div class="practice-copy"><h3>Fikringizni ovoz chiqarib ayting</h3><p>Javobingizni ovozga yozib, qayta eshiting.</p></div><span class="row-meta">Speaking · 1–3 daqiqa</span><span class="row-arrow">↗</span></button><button class="practice-row" data-route="courses"><span class="row-number">03</span><div class="practice-copy"><h3>Qisqa dars bilan davom etish</h3><p>O‘rganish usulini o‘qing va savol bilan tekshiring.</p></div><span class="row-meta">${remaining} ta tugallanmagan</span><span class="row-arrow">↗</span></button></div></section><section class="desk-section"><div class="section-head"><h2>So‘z to‘plamlari</h2><button class="text-btn" data-route="vocab">Kutubxonani ochish →</button></div><div class="library-list">${deckRows()}</div></section></div><aside><section class="day-plan"><div class="section-head"><h2>Bugungi reja</h2><button class="text-btn" data-route="settings">Sozlash</button></div><div class="plan-ring-row"><strong>${today()}</strong><span>/ ${state.goal} kartochka</span></div><div class="progress"><span style="width:${Math.min(100,today()/state.goal*100)}%"></span></div><p class="plan-note">${today()>=state.goal?'Kunlik maqsadingiz bajarildi.':Math.max(0,state.goal-today())+' ta takrorlash qoldi.'}</p><div class="week">${week.map(d=>`<div class="day ${state.log[dateKey(d)]?'done':''}"><span>${state.log[dateKey(d)]?'✓':'·'}</span>${uzDays[d.getDay()]}</div>`).join('')}</div></section><section class="week-summary"><div class="section-head"><h2>Oxirgi 3 hafta</h2><button class="text-btn" data-route="analytics">Batafsil →</button></div><div class="activity-grid">${Array.from({length:21},(_,i)=>{const d=new Date();d.setDate(d.getDate()-20+i);const count=state.log[dateKey(d)]||0;return `<div class="activity-cell ${count?'done':''}" title="${shortDate(d)}: ${count} ta takrorlash"></div>`;}).join('')}</div><small>Har bir belgi — bir kunlik takrorlash.</small><div class="small-metrics"><div>${streak(state.log)}<small>kun ketma-ket</small></div><div>${state.cards.length}<small>so‘z kutubxonada</small></div></div></section><div class="quiet-note"><b>Avval eslang, keyin tekshiring.</b><br>Javobni darhol ochish o‘rniga o‘zingizga bir necha soniya bering. Xato ham keyingi mashq uchun foydali ma’lumot.</div></aside></div>`;}
function vocab(){return heading('SO‘Z BOYLIGINGIZ','Lug‘at & SRS','So‘zlaringizni boshqaring va vaqti kelganda takrorlang.')+`<div class="toolbar"><input id="search" type="search" placeholder="So‘z yoki tarjimani qidirish…" value="${e(search)}" aria-label="So‘z qidirish"><select id="deck-filter" aria-label="To‘plam"><option value="">Barcha to‘plamlar</option>${decks().map(d=>`<option ${d===deckFilter?'selected':''}>${e(d)}</option>`).join('')}</select>${btn('＋ Yangi so‘z','add','primary')}${btn('▤ To‘plam','deck-add')}${btn('↥ Import','import')}${btn('↻ Takrorlash','study','cyan')}</div><section class="panel table-wrap" id="word-table">${wordTable()}</section><p style="font-size:11px">Takrorlash usuli: soddalashtirilgan SM-2. Bahoga qarab keyingi takrorlash vaqti hisoblanadi. FSRS emas.</p>`;}
function wordTable(){const cards=state.cards.filter(c=>(!deckFilter||c.deck===deckFilter)&&normalize(c.word+' '+c.translation).includes(normalize(search)));return `<table><thead><tr><th>SO‘Z / IBORA</th><th>TARJIMA</th><th>TO‘PLAM</th><th>HOLAT</th><th>AMALLAR</th></tr></thead><tbody>${cards.map(c=>`<tr><td>${e(c.word)} <span class="tag">${e(c.level)}</span><small>${e(c.example)}</small></td><td>${e(c.translation)}</td><td>${e(c.deck)}</td><td><span class="tag ${c.due>Date.now()?'green':''}">${c.due>Date.now()?new Date(c.due).toLocaleDateString('uz-UZ'):c.reviews?'Takrorlash':'Yangi'}</span></td><td><button class="icon-btn" data-audio="${e(c.word)}" aria-label="Talaffuz">♫</button> <button class="icon-btn" data-edit="${c.id}" aria-label="Tahrirlash">✎</button> <button class="icon-btn" data-delete="${c.id}" aria-label="O‘chirish">×</button></td></tr>`).join('')}</tbody></table>${cards.length?'':`<div class="empty">Mos so‘z topilmadi. Yangi so‘z qo‘shishingiz mumkin.</div>`}`;}
function addModal(id){const c=state.cards.find(x=>x.id===id)||{word:'',translation:'',example:'',deck:deckFilter||decks()[0]||'Mening so‘zlarim',level:'B2'};openModal(id?'So‘zni tahrirlash':'Yangi so‘z qo‘shish',`<form id="word-form" class="form-grid"><label>Inglizcha so‘z yoki ibora<input name="word" required maxlength="120" value="${e(c.word)}" autofocus></label><label>O‘zbekcha tarjima<input name="translation" required maxlength="500" value="${e(c.translation)}"></label><label>To‘plam<input name="deck" required maxlength="80" list="deck-names" value="${e(c.deck)}"><datalist id="deck-names">${decks().map(d=>`<option value="${e(d)}">`).join('')}</datalist></label><label>Daraja<select name="level">${['A1','A2','B1','B2','C1','C2'].map(l=>`<option ${l===c.level?'selected':''}>${l}</option>`).join('')}</select></label><label class="full">Misol jumla (ixtiyoriy)<input name="example" maxlength="1000" value="${e(c.example)}"></label><label>IPA (ixtiyoriy)<input name="ipa" maxlength="120" placeholder="/rɪˈzɪliənt/" value="${e(c.ipa||'')}"></label><label>So‘z turkumi<input name="pos" maxlength="60" placeholder="adjective" value="${e(c.pos||'')}"></label><label class="full">Misolning o‘zbekcha tarjimasi<input name="exampleUz" maxlength="1000" value="${e(c.exampleUz||'')}"></label><label class="full">Sinonimlar<input name="synonyms" maxlength="500" placeholder="strong, adaptable" value="${e(c.synonyms||'')}"></label><label class="full">Collocation / birikmalar<input name="collocations" maxlength="1000" placeholder="remain resilient; resilient economy" value="${e(c.collocations||'')}"></label><div id="form-error" class="error full"></div><div class="buttons full"><button class="btn primary">Saqlash</button><button class="btn" type="button" data-action="close">Bekor qilish</button></div></form>`);$('#word-form').onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));for(const k in data)data[k]=data[k].trim();if(!data.word||!data.translation||!data.deck)return; if(state.cards.some(x=>x.id!==id&&normalize(x.word)===normalize(data.word)&&normalize(x.deck)===normalize(data.deck))){$('#form-error').textContent='Bu so‘z ushbu to‘plamda allaqachon mavjud.';return;}if(id)Object.assign(c,data);else state.cards.push({...data,id:uid(),reps:0,reviews:0,due:0,ease:2.5,interval:0});save();$('#modal').close();render();toast('So‘z saqlandi');};}
function deckModal(){openModal('Yangi to‘plam yaratish',`<form id="deck-form"><label>To‘plam nomi<input name="deck" required maxlength="80" placeholder="Destination B2 — Unit 1" style="width:100%;margin:10px 0 18px"></label><div id="deck-error" class="error"></div><button class="btn primary">Yaratish</button></form>`);$('#deck-form').onsubmit=ev=>{ev.preventDefault();const name=String(new FormData(ev.target).get('deck')).trim();if(!name)return;if(decks().some(d=>normalize(d)===normalize(name))){$('#deck-error').textContent='Bu nomli to‘plam mavjud.';return;}state.deckNames=[...(state.deckNames||[]),name];save();$('#modal').close();deckFilter=name;search='';location.hash='vocab';if(route==='vocab')render();toast('To‘plam yaratildi. Endi so‘z qo‘shing yoki import qiling.');};}
function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
function importModal(){
 openModal('So‘zlarni import qilish',`<p>Har qatorda <b>inglizcha ; o‘zbekcha ; misol</b> yozing. Excel’dan ikki ustunni ham nusxalash mumkin.</p><form id="import-form"><label>To‘plam nomi<input name="deck" value="${e(deckFilter||'Mening so‘zlarim')}" required maxlength="80" style="width:100%;margin:8px 0 16px"></label><label>So‘zlar<textarea name="text" placeholder="resilient ; bardoshli ; She is resilient.&#10;achieve ; erishmoq" required maxlength="200000"></textarea></label><label style="display:block;margin-top:15px">Yoki fayldan oching (.txt, .tsv, ; bilan ajratilgan .csv)<input type="file" id="import-file" accept=".txt,.tsv,.csv" style="width:100%"></label><div class="error" id="import-error" role="alert"></div><div class="buttons"><button class="btn primary">Ro‘yxatni tekshirish →</button><button class="btn" type="button" data-action="close">Bekor qilish</button></div></form><div id="import-preview"></div><p style="font-size:10px;margin-top:20px">Import tayyor so‘z va tarjimalarni oladi. AI tarjimasi hali ulanmagan.</p>`);
 const form=$('#import-form'),preview=$('#import-preview');let pending=[];
 const invalidate=()=>{pending=[];preview.innerHTML='';$('#import-error').textContent='';};
 form.addEventListener('input',invalidate);
 $('#import-file').onchange=async ev=>{invalidate();const f=ev.target.files[0];if(!f)return;if(f.size>200000){$('#import-error').textContent='Fayl 200 KB dan kichik bo‘lishi kerak.';return;}form.elements.text.value=await f.text();invalidate();};
 form.onsubmit=ev=>{ev.preventDefault();invalidate();const data=new FormData(form),deck=String(data.get('deck')).trim(),{rows,errors}=parseWords(String(data.get('text')),deck);if(!deck)return;
  if(errors.length){$('#import-error').textContent=`${errors.slice(0,20).join(', ')}-qatorni tekshiring: so‘z va tarjima kerak. Hech narsa import qilinmadi.`;return;}
  if(!rows.length){$('#import-error').textContent='Import qilish uchun kamida bitta so‘z kiriting.';return;}
  if(rows.length>1000){$('#import-error').textContent='Bir marta 1000 tagacha so‘z import qilish mumkin.';return;}
  const seen=new Set(state.cards.map(c=>normalize(c.deck)+'\n'+normalize(c.word)));let skipped=0;
  for(const row of rows){const key=normalize(row.deck)+'\n'+normalize(row.word);if(seen.has(key)){skipped++;continue;}seen.add(key);pending.push(row);}
  preview.innerHTML=`<div class="notice"><b>${pending.length} ta yangi so‘z</b> · ${skipped} ta takroriy so‘z o‘tkaziladi.<br>Saqlashdan oldin tarjimalarni tekshiring.</div>${pending.length?`<div class="table-wrap" style="border:1px solid var(--line);max-height:270px"><table style="min-width:450px"><thead><tr><th>INGLIZCHA</th><th>O‘ZBEKCHA</th></tr></thead><tbody>${pending.slice(0,20).map(c=>`<tr><td>${e(c.word)}</td><td>${e(c.translation)}</td></tr>`).join('')}</tbody></table></div>${pending.length>20?'<small>Dastlabki 20 ta so‘z ko‘rsatildi.</small>':''}<div class="buttons"><button type="button" class="btn primary" id="confirm-import">${pending.length} ta so‘zni saqlash</button></div>`:'<p>Yangi so‘z yo‘q. Barcha so‘zlar ushbu to‘plamda mavjud.</p>'}`;
  if($('#confirm-import'))$('#confirm-import').onclick=()=>{if(!pending.length)return;const count=pending.length;for(const row of pending)state.cards.push({...row,id:uid(),reps:0,reviews:0,due:0,ease:2.5,interval:0});pending=[];save();$('#modal').close();render();toast(`${count} ta so‘z saqlandi`);};
 };
}

function startStudy(deck=''){const cards=due().filter(c=>!deck||c.deck===deck);session={ids:cards.map(c=>c.id),index:0,done:0,deck};showBack=false;try{sessionStorage.setItem('lexora.study',JSON.stringify(session));}catch{}location.hash='study';if(route==='study')render();}
function study(){if(!session)return `<div class="empty"><h2>Mashg‘ulotni boshlang</h2>${btn('Takrorlashni boshlash','study','primary')}</div>`;if(session.index>=session.ids.length)return `<div class="empty"><span style="font-size:60px;color:var(--cyan)">✦</span><h1>${session.done?'Ajoyib natija!':'Hozircha hammasi tayyor!'}</h1><p>${session.done?`${session.done} ta kartochka takrorlandi. +${session.done*10} XP.`:'Bu to‘plamda hozir takrorlash vaqti kelgan so‘z yo‘q.'}</p><p>«Yana» deb baholangan so‘z 1 daqiqadan keyin navbatga qaytadi.</p><div class="buttons" style="justify-content:center">${btn('Bosh sahifa','home','primary')}${btn('Lug‘atga qaytish','vocab')}</div></div>`;const c=state.cards.find(c=>c.id===session.ids[session.index]);if(!c){session.index++;return study();}return heading('INTERVALLI TAKRORLASH','Takrorlash','Avval javobni eslashga harakat qiling, keyin ochib tekshiring.')+`<div class="study-top"><span>${e(c.deck)}</span><span>${session.index+1} / ${session.ids.length}</span></div><div class="progress" style="max-width:700px;margin:auto"><span style="width:${session.index/session.ids.length*100}%"></span></div><div class="flashcard"><span class="tag">${e(c.level)} · O‘ZBEKCHA → INGLIZCHA</span><h2 style="margin:35px 0 12px">${e(c.translation)}</h2>${showBack?`<div class="translation">${e(c.word)}</div>${c.ipa||c.pos?`<div class="pronunciation">${e(c.ipa||'')} <span class="tag">${e(c.pos||'')}</span></div>`:''}<button class="icon-btn" data-audio="${e(c.word)}" aria-label="Talaffuzni eshitish">♫ Talaffuz</button><p>${e(c.example)}${c.exampleUz?`<small>${e(c.exampleUz)}</small>`:''}</p>${c.synonyms?`<div class="rich-detail"><b>Sinonimlar</b><span>${e(c.synonyms)}</span></div>`:''}${c.collocations?`<div class="rich-detail"><b>Collocation</b><span>${e(c.collocations)}</span></div>`:''}`:'<p>Inglizchasini eslay olasizmi?</p>'}</div><div class="study-actions">${showBack?['again','hard','good','easy'].map((g,i)=>`<button class="btn ${i===2?'cyan':''}" data-grade="${g}"><span>${['Yana','Qiyin','Yaxshi','Oson'][i]}<small>${g==='again'?'1 daqiqa':schedule(c,g).interval+' kun'}</small></span></button>`).join(''):btn('Javobni ko‘rish ↵','flip','primary')}</div><p class="answer-hint">${showBack?'1–4 tugmalari bilan ham baholashingiz mumkin.':'Space yoki Enter bilan javobni oching.'}</p>`;}
function grade(g){if(!showBack||!session)return;const idx=state.cards.findIndex(c=>c.id===session.ids[session.index]);if(idx<0)return;state.cards[idx]=schedule(state.cards[idx],g);state.xp+=10;state.log[dateKey()]=(state.log[dateKey()]||0)+1;session.index++;session.done++;try{sessionStorage.setItem('lexora.study',JSON.stringify(session));}catch{}showBack=false;save();render();}
function startSpell(){spelling={ids:[...state.cards].sort(()=>Math.random()-.5).slice(0,10).map(c=>c.id),index:0,right:0,mistakes:[],checked:false};location.hash='spell';if(route==='spell')render();}
function spell(){if(!spelling)return heading('YOZMA MASHQ','Imlo mashqi','Tarjimaga qarab inglizcha so‘zni yozing.')+`<section class="flashcard"><span style="font-size:50px;color:var(--purple)">⌨</span><h2 style="font-size:30px">Bilimingizni sinab ko‘ring</h2><p>Lug‘atingizdan 10 tagacha so‘z tanlanadi. Har to‘g‘ri javob uchun 5 XP.</p>${btn('Mashqni boshlash','spell-start','primary')}${!state.cards.length?'<p>Avval lug‘atga so‘z qo‘shing.</p>':''}</section>`;if(spelling.index>=spelling.ids.length)return `<div class="empty"><h1>Mashq yakunlandi ✦</h1><p>${spelling.right} / ${spelling.ids.length} to‘g‘ri javob · +${spelling.right*5} XP</p>${btn('Yana mashq qilish','spell-start','primary')} ${spelling.mistakes.length?btn('Xatolarni qayta mashq qilish','spell-retry','cyan'):''} ${btn('Bosh sahifa','home')}</div>`;const c=state.cards.find(c=>c.id===spelling.ids[spelling.index]);if(!c){spelling.index++;return spell();}return heading('IMLO MASHQI',`${spelling.index+1} / ${spelling.ids.length} so‘z`,'Tarjimaga qarab inglizcha so‘z yoki iborani yozing.')+`<form id="spell-form" class="flashcard"><span class="tag">${e(c.deck)}</span><h2 class="translation" style="font-size:28px;margin-top:30px">${e(c.translation)}</h2><button class="text-btn" type="button" data-audio="${e(c.word)}">♫ Talaffuzni eshitish</button><input class="typing" id="spell-input" autocomplete="off" autocapitalize="off" spellcheck="false" required aria-label="Inglizcha javob" ${spelling.checked?'disabled':''}><div class="result" id="spell-result"></div>${spelling.checked?btn('Keyingi so‘z →','spell-next','primary'):'<button class="btn primary">Javobni tekshirish ↵</button>'}</form>`;}
const lessons=[{id:'context',title:'So‘zni kontekstda o‘rganish',tag:'LUG‘AT · 3 DAQIQA',text:'Yangi so‘zni yakka holda emas, jumlada o‘rganing. «Resilient» — qiyinchilikdan keyin tiklana oladigan. Masalan: “She remained resilient after the setback.” O‘zingizga tegishli bitta misol yozish so‘z bilan shaxsiy bog‘lanish yaratadi.',question:'Qaysi misolda “resilient” to‘g‘ri ishlatilgan?',answers:['She remained resilient after the setback.','She resilient to school yesterday.','I have two resilient.'],correct:0},{id:'collocations',title:'Birga ishlatiladigan so‘zlar',tag:'B2 · 4 DAQIQA',text:'Ingliz tilida ayrim so‘zlar tabiiy juftlik hosil qiladi. Masalan, “make a decision” (qaror qilmoq), “conduct research” (tadqiqot o‘tkazmoq) va “draw a conclusion” (xulosa chiqarmoq). Bularni to‘liq ibora sifatida kartochkaga yozing.',question:'“Qaror qilmoq” uchun to‘g‘ri birikmani tanlang.',answers:['do a decision','make a decision','take research'],correct:1},{id:'review',title:'Takrorlashni odatga aylantirish',tag:'SRS · 2 DAQIQA',text:'Takrorlash paytida avval javobni mustaqil eslashga harakat qiling. So‘ng inglizcha javobni ochib baholang. “Yana” — eslay olmadim; “Qiyin” — zo‘rg‘a esladim; “Yaxshi” — esladim; “Oson” — darhol esladim. Bahoni rost qo‘yish keyingi intervalni moslashtiradi.',question:'Javobni eslay olmasangiz qaysi bahoni tanlaysiz?',answers:['Oson','Yaxshi','Yana'],correct:2}];
function courses(){return heading('QISQA DARSLAR','O‘rganish usullari','Lug‘at o‘rganish usullari bo‘yicha qisqa darslar va bitta savol.')+`<div class="cards">${lessons.map((l,i)=>`<button class="link-card" style="text-align:left" data-lesson="${l.id}"><span class="eyebrow">${l.tag}</span><div style="font-size:42px;color:var(--purple);margin:25px 0">0${i+1}</div><h3>${l.title}</h3><p>${state.completed.includes(l.id)?'✓ Tugallangan':'O‘qish va mashq qilish →'}</p></button>`).join('')}</div><div class="notice">Bu boshlang‘ich mini darslar. To‘liq CEFR kurslari va o‘qituvchi darslari uchun kontent hali qo‘shilmagan.</div>`;}
function lesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;openModal(l.title,`<p class="lesson-text">${l.text}</p><h3>${l.question}</h3><form id="quiz">${l.answers.map((a,i)=>`<label style="display:block;padding:10px 0"><input type="radio" name="answer" value="${i}" required> ${e(a)}</label>`).join('')}<div class="result" id="quiz-result"></div><button class="btn primary">Tekshirish</button></form>`);$('#quiz').onsubmit=ev=>{ev.preventDefault();const correct=Number(new FormData(ev.target).get('answer'))===l.correct;$('#quiz-result').textContent=correct?'To‘g‘ri! Dars tugallandi.':'Hali to‘g‘ri emas. Matnni qayta o‘qib ko‘ring.';if(correct&&!state.completed.includes(id)){state.completed.push(id);state.xp+=15;save();render();}};}
function analytics(){const history=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:d,n:state.log[dateKey(d)]||0};}),max=Math.max(1,...history.map(x=>x.n));return heading('O‘QUV FAOLLIGI','Natijalar','Haqiqiy mashqlaringiz asosida hisoblangan shaxsiy natijalar.')+`<div class="stats">${stat('ϟ',state.xp,'Jami XP')}${stat('↻',Object.values(state.log).reduce((a,b)=>a+b,0),'Takrorlangan kartochkalar')}${stat('⌨',state.spell.total?Math.round(state.spell.right/state.spell.total*100)+'%':'—','Imlo aniqligi')}${stat('♨',streak(state.log),'Ketma-ket kunlar')}</div><div class="grid"><section class="panel"><h2>Oxirgi 7 kun</h2><p style="font-size:11px">Kuniga takrorlangan kartochkalar soni</p><div class="chart">${history.map(h=>`<div class="bar-wrap"><span>${h.n}</span><div class="bar" style="height:${h.n/max*125}px"></div><span>${shortDate(h.date)}</span></div>`).join('')}</div></section><section class="panel"><h2>To‘plamlar bo‘yicha</h2>${decks().map(d=>{const cs=state.cards.filter(c=>c.deck===d),n=cs.filter(c=>c.reps>0).length;return `<div style="margin-top:22px"><div class="goal-row"><span>${e(d)}</span><b>${n} / ${cs.length}</b></div><div class="progress"><span style="width:${cs.length?n/cs.length*100:0}%"></span></div></div>`;}).join('')}</section></div><div class="notice">Umumiy reyting server va foydalanuvchi hisoblari ulangandan so‘ng qo‘shiladi. Hozir boshqa o‘quvchilar uchun soxta natijalar ko‘rsatilmaydi.</div>`;}
function telegram(){return heading('BIRGA O‘RGANISH','Guruhlar','Ustoz materiallari va topshiriqlari uchun umumiy maydon.')+`<div class="grid"><section class="panel"><span class="eyebrow">ULANISH HOLATI</span><h2>Guruhlar keyingi bosqichda ulanadi.</h2><p>Ustoz guruh yaratib, sizga qo‘shilish kodini beradi. Telegram’da ro‘yxatdan o‘tganingizdan so‘ng shu kod bilan guruhga kirasiz.</p><div class="notice">Bu sinov nusxasida guruhga qo‘shilish hali faol emas. Hozirgi mashqlar shaxsiy brauzeringizda saqlanadi.</div><a class="btn" href="https://t.me/lexora_academy_bot" target="_blank" rel="noopener">Lexora botini ochish ↗</a><small>Bot ochilgan, platformaga ulanishi hali yakunlanmagan.</small></section><section class="panel"><h2>Guruhda nimalar bo‘ladi?</h2>${['Ustoz tayyorlagan lug‘at va dars materiallari','Muddatli yozma va og‘zaki topshiriqlar','Javoblar uchun ustoz fikri va qayta topshirish','Guruh ichidagi natijalar va topshiriq bo‘yicha XP'].map((t,i)=>`<div class="lesson-item"><span style="color:var(--muted);margin-right:12px">0${i+1}</span>${t}</div>`).join('')}</section></div>`;}
let designs=[];
async function loadDesigns(){try{designs=await (await fetch('designs.json')).json();if(route==='designs')render();}catch{}}
function designView(){return heading('SIZ YUBORGAN STITCH MANBALARI','Dizaynlar kutubxonasi','Asl ekranlar taqqoslash uchun saqlandi. Ular alohida dizayn namunalari.')+`<div class="cards">${designs.map(d=>`<a class="link-card" href="${e(d.path)}" target="_blank" rel="noopener"><img src="${e(d.image)}" alt="${e(d.name)}" loading="lazy"><h3>${e(d.name)}</h3><span class="text-btn">Asl ekran ↗</span></a>`).join('')}</div>`;}
function settings(){return heading('O‘ZINGIZGA MOSLANG','Sozlamalar','Profil, kunlik maqsad va ma’lumotlaringiz.')+`<div class="settings-grid"><section class="panel"><h2>Shaxsiy sozlamalar</h2><form id="settings-form"><label>Ismingiz<input name="name" value="${e(state.name)}" maxlength="40" required></label><label>Kunlik maqsad (kartochka)<input name="goal" type="number" value="${state.goal}" min="1" max="500" required></label><button class="btn primary">Saqlash</button></form></section><section class="panel"><h2>Ma’lumotlar sizniki</h2><p>So‘zlar va natijalar hozir shu qurilmaning brauzerida saqlanadi. Boshqa qurilmada avtomatik ko‘rinmaydi. Vaqti-vaqti bilan zaxira yuklab oling.</p><div class="buttons">${btn('↓ Zaxira nusxasi','export')}${btn('↥ Zaxiradan tiklash','restore')}</div><p class="callout">${storageOK?'Brauzer xotirasiga saqlash faol.':'Saqlashda muammo bor. Zaxira oling.'}</p></section></div><div class="notice">Hozirgi versiya: funksional MVP. Foydalanuvchi hisoblari, o‘qituvchi/admin rollari, bulut sinxronlash va AI xizmatlari hali ulanmagan.</div>`;}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`lexora-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function restore(){openModal('Zaxira nusxasini tiklash','<p>Lexora JSON zaxirasini tanlang. Tiklash joriy so‘zlar va natijalarni almashtiradi.</p><input type="file" id="backup-file" accept=".json"><p id="backup-result" class="error"></p>');$('#backup-file').onchange=async ev=>{$('#backup-confirm')?.remove();try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Fayl juda katta.');const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.cards)||data.cards.length>10000||typeof data.name!=='string'||!Number.isFinite(data.goal)||data.goal<1||data.goal>500||!Number.isFinite(data.xp)||data.xp<0||!data.log||!data.spell||!Array.isArray(data.completed))throw Error('Lexora zaxirasi formati noto‘g‘ri.');const ids=new Set();for(const c of data.cards){if(typeof c.id!=='string'||ids.has(c.id)||!['word','translation','deck','level','example'].every(k=>typeof c[k]==='string')||!['due','reps','reviews','interval','ease'].every(k=>Number.isFinite(c[k])&&c[k]>=0))throw Error('Kartochkalar formati noto‘g‘ri.');ids.add(c.id);}if(data.deckNames&&(!Array.isArray(data.deckNames)||data.deckNames.some(d=>typeof d!=='string'||d.length>80)))throw Error('To‘plamlar formati noto‘g‘ri.');if(Object.values(data.log).some(v=>!Number.isInteger(v)||v<0)||!Number.isInteger(data.spell.right)||!Number.isInteger(data.spell.total)||data.spell.right<0||data.spell.total<data.spell.right)throw Error('Statistika formati noto‘g‘ri.');$('#backup-result').className='success';$('#backup-result').textContent=`${data.cards.length} ta so‘z topildi.`;const b=document.createElement('button');b.id='backup-confirm';b.className='btn primary';b.textContent='Tasdiqlash va tiklash';b.onclick=()=>{state=data;session=null;spelling=null;try{sessionStorage.removeItem('lexora.study');}catch{}save();$('#modal').close();render();toast('Zaxira tiklandi');};$('#modal-body').append(b);}catch(err){$('#backup-result').textContent=err.message;}};}
function render(){if(route!=='speaking')leaveSpeaking();const pages={home,vocab,study,spell,speaking:speakingView,courses,analytics,telegram,settings,designs:designView};$('#app').innerHTML=(pages[route]||home)();$('#page-name').textContent=nav.find(n=>n[0]===route)?.[2]||(route==='study'?'Takrorlash':'Bosh sahifa');$('#nav').innerHTML=nav.map(([id,icon,title,badge])=>`<a href="#${id}" class="${route===id||route==='study'&&id==='vocab'?'active':''}" ${route===id?'aria-current="page"':''}><span class="icon">${windowIcon(icon)}</span>${title}${badge?`<span class="badge">${badge}</span>`:''}</a>`).join('');updateHeader();if(route==='speaking')mountSpeaking();if(route==='vocab'){$('#search').oninput=ev=>{search=ev.target.value;$('#word-table').innerHTML=wordTable();};$('#deck-filter').onchange=ev=>{deckFilter=ev.target.value;$('#word-table').innerHTML=wordTable();};}if(route==='spell'&&$('#spell-form')){const input=$('#spell-input');if(!spelling.checked)input.focus({preventScroll:true});$('#spell-form').onsubmit=ev=>{ev.preventDefault();if(spelling.checked)return;const c=state.cards.find(c=>c.id===spelling.ids[spelling.index]),correct=normalize(input.value)===normalize(c.word);spelling.checked=true;if(!correct)spelling.mistakes.push(c.id);spelling.right+=correct?1:0;state.spell.total++;state.spell.right+=correct?1:0;state.xp+=correct?5:0;save();const val=input.value;render();$('#spell-input').value=val;$('#spell-result').textContent=correct?'✓ To‘g‘ri! +5 XP':`To‘g‘ri javob: ${c.word}`;$('#spell-result').style.color=correct?'var(--cyan)':'var(--orange)';};}if(route==='settings')$('#settings-form').onsubmit=ev=>{ev.preventDefault();const data=new FormData(ev.target),name=String(data.get('name')).trim();if(!name)return;state.name=name;state.goal=Number(data.get('goal'));save();toast('Sozlamalar saqlandi');render();};}
document.addEventListener('click',ev=>{const t=ev.target.closest('button,a');if(!t)return;if(t.dataset.route){location.hash=t.dataset.route;}if(t.dataset.study!==undefined){startStudy(t.dataset.study);}if(t.dataset.edit)addModal(t.dataset.edit);if(t.dataset.delete){const c=state.cards.find(c=>c.id===t.dataset.delete);openModal('So‘zni o‘chirish',`<p>«${e(c.word)}» so‘zini o‘chirasizmi?</p><button class="btn danger" id="confirm-delete">O‘chirish</button>`);$('#confirm-delete').onclick=()=>{state.cards=state.cards.filter(x=>x.id!==c.id);save();$('#modal').close();render();};}if(t.dataset.audio){if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t.dataset.audio);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u);}else toast('Bu brauzer talaffuzni qo‘llamaydi');}if(t.dataset.grade)grade(t.dataset.grade);if(t.dataset.lesson)lesson(t.dataset.lesson);const actions={'deck-add':deckModal,add:()=>addModal(),import:importModal,close:()=>$('#modal').close(),study:()=>startStudy(),flip:()=>{showBack=true;render();},'spell-start':()=>state.cards.length?startSpell():toast('Avval so‘z qo‘shing'),'spell-retry':()=>{const ids=[...new Set(spelling?.mistakes||[])];if(!ids.length)return;spelling={ids,index:0,right:0,mistakes:[],checked:false};render();},'spell-next':()=>{if(!spelling?.checked)return;spelling.index++;spelling.checked=false;render();},export:exportData,restore,home:()=>location.hash='home',vocab:()=>location.hash='vocab'};actions[t.dataset.action]?.();});
document.addEventListener('keydown',ev=>{if($('#modal').open||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement?.tagName))return;if(route==='study'&&session){if((ev.code==='Space'||ev.key==='Enter')&&!showBack){ev.preventDefault();showBack=true;render();}else if(showBack&&['1','2','3','4'].includes(ev.key)){grade(['again','hard','good','easy'][Number(ev.key)-1]);}}});
function closeMenu(){$('.sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}
$('#menu').onclick=()=>{const opened=$('.sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(opened));};$('#close-menu').onclick=closeMenu;document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeMenu();});document.querySelector('.sidebar').addEventListener('click',ev=>{if(ev.target.closest('a'))closeMenu();});document.addEventListener('click',ev=>{if(!ev.target.closest('.sidebar')&&!ev.target.closest('#menu'))closeMenu();});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';closeMenu();render();window.scrollTo(0,0);});
route=location.hash.slice(1)||'home';render();loadDesigns();
